// Writes the Mac's native text (the `native` area of the catalog) for Rust, one `Native` per shipped language, with every non-ASCII character escaped so the generated file holds none. `--check` fails instead of writing when it is stale (CI runs it).
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'

export const NATIVE_RS = 'src-tauri/src/strings_catalog.rs'
const PREFIX = 'native.'
const CATALOGS = {
  EN: 'src/renderer/src/i18n/en/native.ts',
  ZH_HANS: 'src/renderer/src/i18n/zh-Hans/native.ts',
}

type Catalog = Readonly<Record<string, string>>

export function fieldName(key: string): string {
  if (!key.startsWith(PREFIX)) throw new Error(`E_I18N_RUST_KEY ${key}`)
  const name = key
    .slice(PREFIX.length)
    .replace(/[A-Z0-9]/g, (char) => `_${char.toLowerCase()}`)
    .replace(/_(\d)_/g, '_$1')
  if (!/^[a-z][a-z0-9_]*$/.test(name)) throw new Error(`E_I18N_RUST_KEY ${key}`)
  return name
}

export function rustString(text: string): string {
  const escaped = [...text].map((char) => {
    const code = char.codePointAt(0)!
    if (char === '\\') return '\\\\'
    if (char === '"') return '\\"'
    if (char === '\n') return '\\n'
    if (code < 0x20 || code > 0x7e) return `\\u{${code.toString(16)}}`
    return char
  })
  return `"${escaped.join('')}"`
}

const placeholders = (text: string) =>
  [...text.matchAll(/(?<!\{)\{(\w+)\}(?!\})/g)].map((match) => match[1]!).sort()

/** `Native`, a field per key of `english`, and one static per language; a missing translation is English. */
export function compileNative(
  english: Catalog,
  translations: Readonly<Record<string, Partial<Catalog>>>,
): string {
  const keys = Object.keys(english)
  const names = keys.map(fieldName)
  const twice = names.find((name, i) => names.indexOf(name) !== i)
  if (twice) throw new Error(`E_I18N_RUST_NAME ${twice}`)
  const block = (language: string, catalog: Partial<Catalog>) => {
    const fields = keys.map((key, i) => {
      const text = catalog[key] ?? english[key]!
      if (placeholders(text).join() !== placeholders(english[key]!).join()) {
        throw new Error(`E_I18N_PLACEHOLDERS ${language} ${key}`)
      }
      return `    ${names[i]}: ${rustString(text)},`
    })
    return [`pub static ${language}: Native = Native {`, ...fields, '};']
  }
  return [
    '// Generated by scripts/i18n/rust.ts from src/renderer/src/i18n. Do not edit.',
    '',
    '#[cfg_attr(',
    '    not(target_os = "macos"),',
    '    allow(dead_code, reason = "some menus are macOS only")',
    ')]',
    'pub struct Native {',
    ...names.map((name) => `    pub ${name}: &'static str,`),
    '}',
    '',
    ...block('EN', english),
    ...Object.entries(translations).flatMap(([language, catalog]) => [
      '',
      ...block(language, catalog),
    ]),
    '',
  ].join('\n')
}

export async function nativeStrings(root: string): Promise<string> {
  const load = async (path: string): Promise<Catalog> =>
    (await import(pathToFileURL(join(root, path)).href)).messages
  const { EN, ...rest } = CATALOGS
  const translations: Record<string, Catalog> = {}
  for (const [language, path] of Object.entries(rest)) translations[language] = await load(path)
  return compileNative(await load(EN), translations)
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const root = join(import.meta.dirname, '../..')
  const content = await nativeStrings(root)
  const path = join(root, NATIVE_RS)
  if (process.argv.includes('--check')) {
    if (!existsSync(path) || readFileSync(path, 'utf8') !== content) {
      console.error(`E_STRINGS_STALE ${NATIVE_RS}: run pnpm i18n:apple`)
      process.exit(1)
    }
  } else {
    writeFileSync(path, content)
  }
}
